    let ok: Bool?
    let job: WorkerJob?
    let error: String?
}

nonisolated struct WorkerActiveResponse: Codable {
    let ok: Bool?
    let activeJob: WorkerJob?
}

nonisolated struct WorkerLedgerResponse: Codable {
    let ok: Bool?
    let jobs: [WorkerJob]?
    let ledger: [WorkerJob]?

    var allJobs: [WorkerJob] { jobs ?? ledger ?? [] }
}

