import Foundation

/// Errors surfaced by the IVX production API client.
nonisolated enum IVXAPIError: LocalizedError {
    case invalidURL
    case httpError(Int, String)
    case decodingFailed
    case notAuthenticated
    case network(String)

    var errorDescription: String? {
        switch self {
        case .invalidURL:
            return "Invalid API URL."
        case .httpError(let code, let message):
            return "Server error (\(code)): \(message)"
        case .decodingFailed:
            return "Could not read the server response."
        case .notAuthenticated:
            return "Session expired. Please sign in again."
        case .network(let message):
            return "Network error: \(message)"
        }
    }
}

/// Client for the IVX Holdings production API (`api.ivxholding.com`).
final class IVXAPIService {
    static let shared = IVXAPIService()

    private let baseURL = "https://api.ivxholding.com"
    private let session: URLSession

    private init() {
        let config = URLSessionConfiguration.default
        config.timeoutIntervalForRequest = 45
        config.timeoutIntervalForResource = 90
        session = URLSession(configuration: config)
    }

    // MARK: - Auth

    func ownerLogin(email: String) async throws -> OwnerSession {
        let body = ["email": email]
        let (data, status) = try await post(path: "/api/ivx/owner-passwordless-login", body: body, token: nil)
        guard let decoded = try? JSONDecoder().decode(OwnerLoginResponse.self, from: data) else {
            throw IVXAPIError.decodingFailed
        }
        guard status == 200, let token = decoded.accessToken, !token.isEmpty else {
            let message = decoded.error ?? decoded.message ?? "Login rejected."
            throw IVXAPIError.httpError(status, message)
        }
        return OwnerSession(
            accessToken: token,
            email: decoded.email ?? email,
            userId: decoded.userId,
            obtainedAt: Date()
        )
    }

    // MARK: - Owner AI Chat

    func sendOwnerAIMessage(
        _ message: String,
        conversationId: String?,
        token: String
    ) async throws -> OwnerAIResponse {
        var body: [String: String] = ["message": message]
        if let conversationId, !conversationId.isEmpty {
            body["conversationId"] = conversationId
        }
        let (data, status) = try await post(path: "/api/ivx/owner-ai", body: body, token: token)
        if status == 401 { throw IVXAPIError.notAuthenticated }
        guard let decoded = try? JSONDecoder().decode(OwnerAIResponse.self, from: data) else {
            throw IVXAPIError.decodingFailed
        }
        guard status == 200 else {
            throw IVXAPIError.httpError(status, decoded.error ?? "Chat request failed.")
        }
        return decoded
    }

    // MARK: - Senior Developer Worker

    func enqueueWorkerJob(
        goal: String,
        templateMode: String,
        approveGitDeploy: Bool,
        token: String
    ) async throws -> WorkerEnqueueResponse {
        var body: [String: Any] = [
            "goal": goal,
            "templateMode": templateMode,
            "approvePatch": approveGitDeploy,
            "approveGitDeploy": approveGitDeploy,
        ]
        if approveGitDeploy {
            body["proposedPlan"] = "Implement the goal exactly as described, run tests and health checks, then deploy."
            body["filesAffected"] = ["to-be-determined-by-worker"]
            body["riskLevel"] = "LOW"
            body["rollbackOption"] = "git revert the produced commit on main"
        }
        let (data, status) = try await postJSON(path: "/api/ivx/senior-developer/worker/jobs", json: body, token: token)
        if status == 401 { throw IVXAPIError.notAuthenticated }
        guard let decoded = try? JSONDecoder().decode(WorkerEnqueueResponse.self, from: data) else {
            throw IVXAPIError.decodingFailed
        }
        // 202 = created, 409 = attached to running job — both are valid outcomes.
        guard status == 202 || status == 409 || status == 200 else {
            throw IVXAPIError.httpError(status, decoded.error ?? decoded.message ?? "Job enqueue failed.")
        }
        return decoded
    }

    func fetchWorkerJob(jobId: String, token: String) async throws -> WorkerJob? {
        let (data, status) = try await get(path: "/api/ivx/senior-developer/worker/jobs/\(jobId)", token: token)
        if status == 401 { throw IVXAPIError.notAuthenticated }
        let decoded = try? JSONDecoder().decode(WorkerJobDetailResponse.self, from: data)
        return decoded?.job
    }

    func fetchActiveJob(token: String) async throws -> WorkerJob? {
        let (data, status) = try await get(path: "/api/ivx/senior-developer/worker/active", token: token)
        if status == 401 { throw IVXAPIError.notAuthenticated }
        let decoded = try? JSONDecoder().decode(WorkerActiveResponse.self, from: data)
        return decoded?.activeJob
    }

    func fetchLedger(token: String) async throws -> [WorkerJob] {
        let (data, status) = try await get(path: "/api/ivx/senior-developer/worker/ledger", token: token)
        if status == 401 { throw IVXAPIError.notAuthenticated }
        let decoded = try? JSONDecoder().decode(WorkerLedgerResponse.self, from: data)
        return decoded?.allJobs ?? []
    }

    func fetchWorkerStatus(token: String) async throws -> WorkerStatusResponse? {
        let (data, status) = try await get(path: "/api/ivx/senior-developer/worker/status", token: token)
        if status == 401 { throw IVXAPIError.notAuthenticated }
        return try? JSONDecoder().decode(WorkerStatusResponse.self, from: data)
    }

    // MARK: - Health (public)

    func fetchHealth() async throws -> HealthResponse {
        let (data, status) = try await get(path: "/health", token: nil)
        guard status == 200, let decoded = try? JSONDecoder().decode(HealthResponse.self, from: data) else {
            throw IVXAPIError.httpError(status, "Health endpoint unavailable.")
        }
        return decoded
    }

    // MARK: - Transport

    private func get(path: String, token: String?) async throws -> (Data, Int) {
        guard let url = URL(string: baseURL + path) else { throw IVXAPIError.invalidURL }
        var request = URLRequest(url: url)
        request.httpMethod = "GET"
        if let token {
            request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
        }
        return try await execute(request)
    }

    private func post(path: String, body: [String: String], token: String?) async throws -> (Data, Int) {
        try await postJSON(path: path, json: body, token: token)
    }

